@pytest.mark.parametrize("publication_write", [1, 2], ids=["settlement-write", "final-notification-write"]) def test_terminal_persistence_in_flight_cannot_publish_or_adopt(creative_model, monkeypatch, publication_write): """A successful ledger is insufficient until the original worker publishes.""" e = creative_model row, calls = ready(e, monkeypatch) entered, release = Event(), Event() original = e.manager._persist writes = 0 def blocked(job): nonlocal writes if job.status == "COMPLETED" and job.terminal_hook_status == "COMPLETED": writes += 1 if writes == publication_write: entered.set() assert release.wait(15), "test publication barrier was not released" raise OSError("synthetic terminal publication failure") return original(job) monkeypatch.setattr(e.manager, "_persist", blocked) running = dispatch(e, row) job = e.manager.get(running["model_execution"]["job_id"]) try: assert entered.wait(10), "worker did not reach the controlled publication boundary" response = e.client.post(e.creative_base + f'/adaptation-proposals/{row["id"]}/refresh', headers=e.headers, json={"expected_version": running["version"]}) result = checked(response) if result.get("output") is not None: # On the old implementation this is a real successful write before # the worker reports its injected persistence failure. checked(review(e, result)) > assert result["status"] == "GENERATING" and result["output"] is None E AssertionError: assert ('NEEDS_REVIEW' == 'GENERATING' E E - GENERATING E + NEEDS_REVIEW)
